#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
int main(){int n,k;cin>>n>>k;map<int,int>freq;int ordinary=0;for(int i=0,v;i<n;i++){cin>>v;bool lucky=true;for(int x=v;x;x/=10)if(x%10!=4&&x%10!=7)lucky=false;if(lucky)freq[v]++;else ordinary++;}int groups=freq.size();vector<ll>dp(min(groups,k)+1);dp[0]=1;int done=0;for(auto[v,c]:freq){done++;for(int j=min({done,groups,k});j>=1;j--)dp[j]=(dp[j]+dp[j-1]*c)%1000000007;}vector<ll>fact(ordinary+1,1),inv= fact;for(int i=1;i<=ordinary;i++)fact[i]=fact[i-1]*i%1000000007;inv[ordinary]=power(fact[ordinary],1000000005);for(int i=ordinary;i;i--)inv[i-1]=inv[i]*i%1000000007;ll ans=0;for(int j=0;j<(int)dp.size();j++)if(k-j<=ordinary)ans=(ans+dp[j]*fact[ordinary]%1000000007*inv[k-j]%1000000007*inv[ordinary-k+j])%1000000007;cout<<ans<<'\n';}
